10	/* Refer & earn + the partner programme, on ONE page.
11	 *
12	 * They were two routes — /refer and /affiliate — describing the same thing to
13	 * the same person in two different vocabularies, plus /partner for the agency
14	 * side. This is the customer-facing half of the concept's Affiliates screen,
15	 * with the partner half shown only to an account that actually IS one.
16	 *
17	 * EVERY FIGURE HERE IS REAL. The concept's "10% shared hosting / 5% VPS" cards
18	 * are NOT reproduced: this platform pays a FLAT per-referral credit
19	 * (`referral_reward_cents`, $5 by default) and percentage commission exists only
20	 * on the partner side (`ReferralPartner.commissionRatePct`). Printing the
21	 * percentages would advertise a scheme the money code does not run.
22	 */
23	
24	async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
25	  if (current) return current;
26	  for (let i = 0; i < 6; i++) {
27	    const code = generateReferralCode();
28	    if (await db.user.findUnique({ where: { referralCode: code } })) continue;
29	    try {
30	      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
31	      return code;
32	    } catch { /* unique clash race — retry */ }
33	  }
34	  const fallback = generateReferralCode(12);
35	  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
36	  return fallback;
37	}
