76	      select: { createdAt: true, referralRewardedAt: true },
77	    });
78	    for (let i = 5; i >= 0; i--) { series.signups.push(0); series.credit.push(0); }
79	    for (const r of rows) {
80	      const idx = (r.createdAt.getFullYear() - now.getFullYear()) * 12
81	                + (r.createdAt.getMonth() - now.getMonth()) + 5;
82	      if (idx < 0 || idx > 5) continue;
83	      series.signups[idx] += 1;
84	      if (r.referralRewardedAt) series.credit[idx] += rewardCents;
85	    }
86	  }
87	
88	  return (
89	    <RewardsView
90	      code={code}
91	      link={`${process.env.APP_URL ?? "https://nxeon.cloud"}/r/${code}`}
92	      rewardCents={rewardCents}
93	      total={total}
94	      rewarded={rewarded}
95	      thisMonth={thisMonth}
96	      lastMonth={lastMonth}
97	      clicks={clicks}
98	      convertedClicks={convertedClicks}
99	      rank={current}
100	      series={series}
101	      nextRank={next}
102	      /* Earned is what has ACTUALLY been credited: the flat reward times the
103	         referrals that reached the rewarded state. Pending is the rest — signed
104	         up, not yet qualified — and is labelled as such rather than counted. */
105	      earnedCents={rewarded * rewardCents}
106	      pendingCents={Math.max(0, total - rewarded) * rewardCents}
107	      recent={recent.map((r) => ({
108	        name: r.name || r.email.split("@")[0],
109	        email: r.email,
110	        joined: r.createdAt.toISOString(),
111	        rewarded: !!r.referralRewardedAt,
112	      }))}
113	      partner={partner ? {
