import { NextRequest, NextResponse } from "next/server";
import { PROMO_CAMPAIGN_COOKIE, sanitizeCampaign } from "@/lib/promo-redemption";

/**
 * Ad-bound entry link for the managed first-month-free promo.
 *
 *   /go/first-month-free?c=<campaign>
 *
 * Drops a short-lived `nx_promo_campaign` cookie carrying the (sanitized)
 * campaign tag, then 302-redirects the visitor into the funnel (/pricing). Every
 * order flow reads that cookie into the PromoRedemption's `campaign` field, so a
 * click that later converts is attributed to the ad that sent it — the same tag
 * the Meta/Google pixel already fires on, giving the admin Promotions page a
 * per-campaign conversion (renewed / total) view.
 *
 * The cookie is NOT httpOnly on purpose: it carries no secret, only an ad label,
 * and client-side pixel code may want to read it too. It is sanitized to a
 * bounded alnum-dash slug so nothing hostile can ride in on it, and expires in a
 * few days so a stale campaign tag never sticks to an unrelated later purchase.
 */

const DEST: Record<string, string> = {
  "first-month-free": "/pricing",
};

const CAMPAIGN_TTL_SECONDS = 60 * 60 * 24 * 3; // 3 days

export async function GET(req: NextRequest, { params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const dest = DEST[slug];
  // Unknown slug: send them somewhere sensible rather than 404 an ad click.
  const target = dest ?? "/";

  const campaign = sanitizeCampaign(req.nextUrl.searchParams.get("c"));
  // Redirect against the PUBLIC origin, not req.nextUrl.origin: behind the nginx
  // proxy the request origin resolves to http://localhost:3000, so an ad click
  // would 302 the visitor to localhost. APP_URL is the canonical public base.
  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
  const res = NextResponse.redirect(new URL(target, publicOrigin), 302);

  // Only set the attribution cookie for a real promo slug with a campaign tag.
  if (dest && campaign) {
    res.cookies.set(PROMO_CAMPAIGN_COOKIE, campaign, {
      path: "/",
      maxAge: CAMPAIGN_TTL_SECONDS,
      sameSite: "lax",
    });
  }
  return res;
}

