import { NextRequest, NextResponse } from "next/server";

/**
 * Shareable referral link: /r/<code>, printed on the Refer & Earn page
 * (app/dashboard/refer/page.tsx) as `${APP_URL}/r/${code}`.
 *
 * Drops the same `nxeon_ref` cookie that `ReferralCapture` sets client-side for
 * the `?ref=` query-param case, then 302-redirects to /register. No DB lookup
 * here on purpose: `register` (lib/actions.ts, ~line 203) already only honors a
 * cookie value that matches a real `User.referralCode` or `ReferralPartner.code`
 * — this route's only job is translating the short link into that cookie.
 */

const REF_COOKIE = "nxeon_ref";
const REF_COOKIE_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days, matches ReferralCapture

export async function GET(req: NextRequest, { params }: { params: Promise<{ code: string }> }) {
  const { code: rawCode } = await params;

  // Redirect against the PUBLIC origin, not req.nextUrl.origin: behind the nginx
  // proxy the request origin resolves to http://localhost:3000 (see app/go/[slug]).
  const publicOrigin = process.env.APP_URL ?? req.nextUrl.origin;
  const res = NextResponse.redirect(new URL("/register", publicOrigin), 302);

  const code = rawCode.trim().toUpperCase().slice(0, 32);
  if (/^[A-Z0-9_-]+$/.test(code)) {
    res.cookies.set(REF_COOKIE, code, {
      path: "/",
      maxAge: REF_COOKIE_TTL_SECONDS,
      sameSite: "lax",
    });
  }
  return res;
}

