1	"use server";
2	
3	// Server actions behind the "card on file" section of the customer billing page.
4	//
5	// The whole flow is redirect-based (Stripe hosted Checkout in `mode: "setup"`),
6	// because no Stripe Elements / Stripe.js integration exists in this codebase and
7	// no publishable key is plumbed to the browser. That means there is a moment where
8	// the card exists at Stripe and not here, which is exactly the shape of the
9	// fulfilment bug that cost a customer their server once already — see
10	// `adoptUnclaimedCards` in `lib/stripe-cards.ts` for the backstop.
11	//
12	// ROUTE NOTE: `app/api/stripe/**` is owned elsewhere, so the return leg is NOT an
13	// API route. Stripe redirects to `/dashboard/billing?card_setup=<session_id>` and
14	// a small client component calls `finalizeCardSetup` below. If a route is wanted
15	// later, the natural one is `GET /api/stripe/setup-return?session_id=…` calling
16	// `saveCardFromSetupSession(sessionId, currentUser().id)` and redirecting to
17	// `/dashboard/billing?card=saved`.
18	
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { stripeConfigured, type EmbeddedCheckout } from "./stripe";
23	import { walletSplit } from "./wallet-split";
24	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
25	import { annualDiscountPct } from "./annual-discount";
26	import { extraDiskPerGbCents } from "./disk-expand";
27	import { backupPlusMonthlyCents } from "./backup-upgrade";
28	import { taxContextForUser } from "./tax";
29	import {
30	  CARD_REMOVED,
31	  CARD_SETUP_STARTED,
32	  cardDisplayLabel,
33	  createCardSetupSession,
34	  createOutstandingEmbedded,
35	  detachSavedCard,
36	  renewalCharge,
37	  retryDunningNow,
38	  saveCardFromSetupSession,
39	} from "./stripe-cards";
40	
41	/**
42	 * Begin saving a card. Returns the hosted Checkout URL for the browser to follow.
43	 *
44	 * The `card.setup_started` audit row is not just bookkeeping: it is the evidence
45	 * `adoptUnclaimedCards` requires before it will adopt a card that is attached at
46	 * Stripe but was never confirmed here, which is what keeps a REMOVED card from
47	 * being silently resurrected.
48	 */
49	export async function startCardSetup(): Promise<{ clientSecret?: string; publishableKey?: string; error?: string }> {
50	  // An admin impersonating a customer must not be able to put a card on their
51	  // account — the same reasoning that blocks impersonated wallet spend.
52	  await assertNotImpersonating();
53	  const user = await requireUser();
54	  if (!stripeConfigured()) {
55	    return { error: "Card payments aren't configured on this installation yet." };
56	  }
57	  try {
58	    const res = await createCardSetupSession(user);
59	    if (!res) return { error: "Stripe didn't return a setup session. Please try again." };
60	    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
61	    return { clientSecret: res.clientSecret, publishableKey: res.publishableKey };
62	  } catch (e) {
63	    console.error("[payment-method] setup session failed", e);
64	    return { error: "We couldn't start card setup just now. Please try again in a moment." };
65	  }
66	}
67	
68	/**
69	 * Finish saving a card after Stripe redirects back.
70	 *
71	 * Safe to call repeatedly with the same session id — it re-reads the same payment
72	 * method from Stripe and writes the same columns, so a refreshed tab is a no-op
73	 * rather than a second card.
74	 */
75	export async function finalizeCardSetup(
76	  sessionId: string,
77	): Promise<{ ok?: boolean; label?: string; error?: string }> {
78	  await assertNotImpersonating();
79	  const user = await requireUser();
80	  if (!sessionId) return { error: "Missing card setup reference." };
81	
82	  const res = await saveCardFromSetupSession(sessionId, user.id);
83	  if (res.error || !res.card) return { error: res.error ?? "The card wasn't saved." };
84	
85	  const label = cardDisplayLabel(res.card) ?? "Card saved";
86	  await db.auditLog.create({ data: { userId: user.id, action: "card.saved", detail: label } });
87	  // Anyone mid-dunning was told we'd charge a new card straight away; make it true.
88	  const requeued = await retryDunningNow(user.id);
89	  if (requeued > 0) {
90	    await db.notification.create({
91	      data: {
92	        userId: user.id,
93	        title: "Card saved — we'll retry your renewal shortly",
94	        body: `We'll charge ${label} for the outstanding renewal within the next few minutes. Nothing is suspended.`,
95	        href: "/dashboard/billing",
96	      },
97	    });
98	  }
99	  revalidatePath("/dashboard/billing");
100	  return { ok: true, label };
101	}
102	
103	/** Remove the card on file (detaches at Stripe first — see `detachSavedCard`). */
104	export async function removeSavedCard(): Promise<{ ok?: boolean; error?: string }> {
105	  await assertNotImpersonating();
106	  const user = await requireUser();
107	  const label = cardDisplayLabel({
108	    brand: user.cardBrand,
109	    last4: user.cardLast4,
110	    expMonth: user.cardExpMonth,
111	    expYear: user.cardExpYear,
112	  });
113	  const res = await detachSavedCard(user.id);
114	  if (res.error) return { error: res.error };
115	  await db.auditLog.create({
116	    data: { userId: user.id, action: CARD_REMOVED, detail: label ?? "card on file" },
117	  });
118	  revalidatePath("/dashboard/billing");
119	  return { ok: true };
120	}
121	
122	/**
123	 * Mint a FRESH hosted-Checkout link for a server's outstanding renewal balance.
124	 *
125	 * A link is minted on demand rather than reusing the stored `dunningPayUrl`
126	 * because Stripe Checkout sessions expire within 24 hours while the dunning
127	 * sequence runs for six days — surfacing the stored link in the portal would show
128	 * an expired Stripe page to a customer trying to pay us.
129	 */
130	export async function settleOutstanding(
131	  serverId: string,
132	): Promise<{ checkout?: EmbeddedCheckout; error?: string; covered?: boolean }> {
133	  const user = await requireUser();
134	  if (!stripeConfigured()) {
135	    return { error: "Card payments aren't configured — add funds to your wallet instead." };
136	  }
137	  const server = await db.server.findUnique({
138	    where: { id: serverId },
139	    include: { plan: true, gamePlan: true, dedicatedIp: true, user: true },
140	  });
141	  if (!server) return { error: "Server not found." };
142	  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
143	  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };
144	
145	  // EVERY figure below is the OWNER's, never the caller's.
146	  //
147	  // The admin branch above lets staff mint this link on a customer's behalf, and
148	  // until now the split was computed from `user.balanceCents` and the session was
149	  // stamped with `user.id` — the ADMIN's wallet and the ADMIN's account. So an
150	  // admin settling a customer's balance quoted a remainder against their own
151	  // credit and produced a Checkout session whose payment credits the admin's
152	  // wallet, leaving the customer's server exactly as unpaid as before. Worse, the
153	  // link is stored on `Server.dunningPayUrl` and `worker/billing.ts` reuses a
154	  // stored link verbatim in the "your bank needs to confirm" email — so the
155	  // CUSTOMER would be emailed a page that pays money into someone else's wallet.
156	  // The balance belongs to the server's owner, so the whole quote does.
157	  const owner = server.user;
158	  const charge = renewalCharge(server, {
159	    ipMonthlyCents: await dedicatedIpMonthlyCents(),
160	    extraDiskPerGbCents: await extraDiskPerGbCents(),
161	    backupPlusCents: await backupPlusMonthlyCents(),
162	    annualDiscountPct: await annualDiscountPct(),
163	    // VAT/GST for the owner's country (Finding 1) so this quoted card leg matches the
164	    // tax-inclusive total the sweep will debit — quote here === charge there.
165	    taxRatePercent: (await taxContextForUser(owner)).ratePercent,
166	  });
167	  // Wallet credit first, card for the remainder — the same split the sweep will
168	  // apply, so the quote here and the charge there can never disagree.
169	  const split = walletSplit({
170	    dueCents: charge.totalCents,
171	    balanceCents: owner.balanceCents,
172	    useWallet: true,
173	  });
174	  if (split.cardCents === 0) {
175	    return {
176	      covered: true,
177	      error:
178	        server.userId === user.id
179	          ? "Your wallet already covers this renewal — it completes automatically within a few minutes."
180	          : "This customer's wallet already covers the renewal — it completes automatically within a few minutes.",
181	    };
182	  }
183	
184	  const checkout = await createOutstandingEmbedded({
185	    user: owner,
186	    amountCents: split.cardCents,
187	    hostname: server.hostname,
188	    serverId: server.id,
189	  });
190	  if (!checkout) return { error: "We couldn't start checkout just now. Please try again in a moment." };
191	  // Deliberately DON'T write `dunningPayUrl`: an embedded session has no URL, and
192	  // that column is the worker's "dunning email already sent" sentinel + the hosted
193	  // link it mints for the inbox. The worker keeps its own hosted link current; this
194	  // in-portal modal is a parallel way to pay the same balance (both credit the
195	  // wallet, the sweep applies it — paying twice just banks surplus credit).
196	  return { checkout };
197	}
