135	type FinalizeState =
136	  | { kind: "working" }
137	  | { kind: "saved"; label: string }
138	  | { kind: "failed"; error: string };
139	
140	/**
141	 * Completes card setup after Stripe redirects back to
142	 * `/dashboard/billing?card_setup=<session_id>`.
143	 *
144	 * Two things this must not be:
145	 *  - a silent no-op. Checkout attaches the card at Stripe BEFORE this ever runs,
146	 *    so a customer who lands here and sees nothing has a card at Stripe and none
147	 *    on file with us — and would be dunned for it.
148	 *  - a dead end. If finalising fails, the card may still be saved at Stripe, and
149	 *    the worker's `adoptUnclaimedCards` backstop claims it on the next sweep. The
150	 *    failure copy says exactly that, and still offers a retry.
151	 *
152	 * `finalizeCardSetup` is documented as safe to call repeatedly with the same
153	 * session id, so a refreshed tab re-reads the same payment method rather than
154	 * saving a second card. The ref below is not for correctness, only to stop React's
155	 * development double-mount from firing two identical round-trips.
156	 */
157	export function CardSetupReturn({ sessionId }: { sessionId: string }) {
158	  const router = useRouter();
159	  const fired = useRef(false);
160	  const [state, setState] = useState<FinalizeState>({ kind: "working" });
161	  const canceled = sessionId === "canceled";
162	
163	  useEffect(() => {
164	    if (canceled || fired.current) return;
165	    fired.current = true;
166	    void (async () => {
167	      const res = await finalizeCardSetup(sessionId);
168	      if (res.ok) {
169	        setState({ kind: "saved", label: res.label ?? "Card saved" });
170	        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
171	        // card label). Best-effort: a no-op until consent + the pixel load.
172	        try {
173	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
174	        } catch {
175	          /* ignore */
176	        }
177	        // Drop the one-shot session id from the URL so a refresh or a shared link
178	        // doesn't replay the return leg, then pull the page's server data again —
179	        // the action has already revalidated it.
180	        router.replace("/dashboard/billing");
181	        router.refresh();
182	        return;
183	      }
184	      setState({ kind: "failed", error: res.error ?? "The card wasn't saved." });
185	    })();
186	  }, [sessionId, canceled, router]);
187	
188	  if (canceled) {
189	    return (
190	      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
191	        <p className="text-sm font-medium text-amber-300">Card setup canceled</p>
192	        <p className="mt-1 text-sm text-slate-400">
193	          No card was saved and nothing was charged. Your renewals will keep coming out of your
194	          wallet balance until a card is on file.
195	        </p>
196	        <div className="mt-3">
197	          <AddCardButton label="Try again" className="btn-secondary py-1.5" />
198	        </div>
199	      </div>
200	    );
201	  }
202	
203	  if (state.kind === "working") {
204	    return (
205	      <div className="card border-white/[0.08] text-sm text-slate-400">
206	        Finishing card setup — one moment.
207	      </div>
208	    );
209	  }
210	
211	  if (state.kind === "saved") {
212	    return (
213	      <div className="card border-emerald-500/30 bg-emerald-500/[0.06]">
214	        <p className="text-sm font-medium text-emerald-300">{state.label} saved</p>
215	        <p className="mt-1 text-sm text-slate-400">
216	          Renewals will now charge this card for anything your wallet balance doesn&apos;t cover.
217	        </p>
218	      </div>
219	    );
220	  }
221	
222	  return (
223	    <div className="card border-red-500/30 bg-red-500/[0.06]">
224	      <p className="text-sm font-medium text-red-300">We couldn&apos;t finish saving your card</p>
225	      <p className="mt-1 text-sm text-slate-400">{state.error}</p>
226	      <p className="mt-2 text-xs text-slate-500">
227	        If you completed the form on Stripe&apos;s page, the card may already be saved on their side
228	        — we check for that automatically and it will appear here within a few minutes. Nothing was
229	        charged either way.
230	      </p>
231	      <div className="mt-3">
232	        <AddCardButton label="Try again" className="btn-secondary py-1.5" />
233	      </div>
234	    </div>
235	  );
236	}
