9	/* Billing, on the concept's structure.
10	 *
11	 * EVERY FIGURE IS COMPUTED FROM RECORDS, not estimated. The six-month chart is
12	 * a GROUP BY over paid invoices; "next charge" is the earliest real expiry
13	 * across the things that actually renew; "active services" counts them; the
14	 * month-over-month percentage is last calendar month's real paid total, not a
15	 * guess; the usage tab's bytes come straight from the same meter the worker
16	 * writes (`lib/bandwidth.ts`), including its "not measured yet" state — never
17	 * a synthesized 0%.
18	 *
19	 * The concept's "Your Plan — Nexion Pro, $24.99/mo" card is deliberately NOT
20	 * here. Nxeon has no account-level subscription — it sells per service — so
21	 * that card would describe a product that does not exist. The active-services
22	 * figure says the true version of the same thing.
23	 */
24	export default async function BillingPage() {
25	  const user = await requireUser();
26	  const now = new Date();
27	  const sixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);
28	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
29	  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
30	
31	  const [invoices, paidSince, monthInvoices, lastMonthInvoices, servers, hosting, domains, bwServers] = await Promise.all([
32	    db.invoice.findMany({
33	      where: { userId: user.id },
34	      select: {
35	        id: true, number: true, amountCents: true, taxCents: true, status: true,
36	        description: true, paidAt: true, periodStart: true, refundedCents: true,
37	      },
38	      orderBy: { number: "desc" },
39	      take: 60,
40	    }),
41	    db.invoice.findMany({
42	      where: { userId: user.id, status: "PAID", paidAt: { gte: sixMonthsAgo } },
43	      select: { amountCents: true, taxCents: true, paidAt: true },
44	    }),
45	    db.invoice.aggregate({
46	      where: { userId: user.id, status: "PAID", paidAt: { gte: monthStart } },
47	      _sum: { amountCents: true, taxCents: true },
48	    }),
49	    db.invoice.aggregate({
50	      where: { userId: user.id, status: "PAID", paidAt: { gte: lastMonthStart, lt: monthStart } },
51	      _sum: { amountCents: true, taxCents: true },
52	    }),
53	    db.server.findMany({
54	      where: { userId: user.id, status: { notIn: ["DELETING"] } },
55	      select: { hostname: true, expiresAt: true, autoRenew: true },
56	    }),
57	    db.hostingAccount.findMany({
58	      where: { userId: user.id, status: { in: ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] } },
59	      select: { primaryDomain: true, expiresAt: true },
60	    }),
61	    db.domain.findMany({
62	      where: { userId: user.id, status: "ACTIVE" },
63	      select: { name: true, expiresAt: true },
64	    }),
65	    db.server.findMany({
66	      where: { userId: user.id, status: { not: "DELETING" } },
67	      select: { hostname: true, status: true, bwInBytes: true, bwOutBytes: true, bwWindowStart: true, plan: { select: { bandwidthTB: true } } },
68	      orderBy: { createdAt: "asc" },
69	    }),
70	  ]);
71	
72	  /* Six calendar months, oldest first, zero-filled. A month with no spend is a
73	     zero bar rather than a gap — a chart that silently drops empty months
74	     misrepresents the shape of the spend. */
75	  const buckets: { label: string; cents: number }[] = [];
76	  for (let i = 5; i >= 0; i--) {
77	    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
78	    buckets.push({ label: d.toLocaleDateString(undefined, { month: "short" }), cents: 0 });
79	  }
80	  for (const inv of paidSince) {
81	    if (!inv.paidAt) continue;
82	    const idx = (inv.paidAt.getFullYear() - now.getFullYear()) * 12 + (inv.paidAt.getMonth() - now.getMonth()) + 5;
83	    if (idx >= 0 && idx < 6) buckets[idx].cents += inv.amountCents + inv.taxCents;
84	  }
85	
86	  const monthCents = (monthInvoices._sum.amountCents ?? 0) + (monthInvoices._sum.taxCents ?? 0);
87	  const lastMonthCents = (lastMonthInvoices._sum.amountCents ?? 0) + (lastMonthInvoices._sum.taxCents ?? 0);
88	  // Withheld rather than shown as 0%/∞% when there is nothing real to compare
89	  // against — a made-up percentage is worse than none.
90	  const monthPct = lastMonthCents > 0 ? Math.round(((monthCents - lastMonthCents) / lastMonthCents) * 100) : null;
91	
92	  // An admin impersonating a customer must not be able to attach, remove or
93	  // use a card on their account (lib/actions-payment-method.ts refuses these
94	  // server-side) — the controls are hidden rather than left to throw on click.
95	  const isImpersonating = (await impersonating()) !== null;
96	
97	  const renewables = [
98	    ...servers.map((s) => ({ name: s.hostname, kind: "Server", at: s.expiresAt, auto: s.autoRenew })),
99	    ...hosting.map((h) => ({ name: h.primaryDomain, kind: "Hosting", at: h.expiresAt, auto: true })),
100	    ...domains.map((d) => ({ name: d.name, kind: "Domain", at: d.expiresAt, auto: true })),
101	  ].filter((r) => r.at) as { name: string; kind: string; at: Date; auto: boolean }[];
102	  renewables.sort((a, b) => a.at.getTime() - b.at.getTime());
103	  const next = renewables[0] ?? null;
104	  const daysUntilNext = next ? Math.max(0, Math.round((next.at.getTime() - now.getTime()) / 86_400_000)) : null;
105	
106	  // Same meter the worker sweeps and the same "measured" gate the original
107	  // dashboard's Usage panel uses — a server this has never metered reports
108	  // that honestly instead of a fabricated 0%.
109	  const cards = await listPaymentCards(user.id);
110	
111	  const bwHealth = await readBwMeterHealth();
112	  const bandwidth = bwServers.map((s) => {
113	    const view = bwUsageView(s, (s.plan?.bandwidthTB ?? 0) * 1e12, bwHealth);
114	    return {
115	      hostname: s.hostname,
116	      measured: view.measured,
117	      usedBytes: view.usedBytes,
118	      allowanceBytes: view.allowanceBytes,
119	      pct: view.pct,
120	      partial: view.partial,
121	    };
122	  });
123	
124	  return (
125	    <BillingView
126	      balanceCents={user.balanceCents}
127	      totalSixMonthCents={buckets.reduce((n, b) => n + b.cents, 0)}
128	      monthCents={monthCents}
129	      monthPct={monthPct}
130	      buckets={buckets}
131	      activeServices={servers.length + hosting.length + domains.length}
132	      next={next ? { name: next.name, kind: next.kind, at: next.at.toISOString() } : null}
133	      daysUntilNext={daysUntilNext}
134	      /* The summary line, which is one entry per KIND of method — not the full
135	         card list. The account's PRIMARY card is the one mirrored onto `User`
136	         (brand/last4/expiry cached for display), and there is at most one
137	         vaulted PayPal (`paypalVaultId`). Every saved card, including the
138	         non-primary ones, rides the `cards` prop below from
139	         `listPaymentCards` — a customer may have several. */
140	      methods={[
141	        ...(hasChargeableCard(user) && user.cardLast4 ? [{
142	          kind: "card" as const,
143	          label: user.cardBrand ?? "Card",
144	          detail: `•••• ${user.cardLast4}`,
145	          expires: user.cardExpMonth && user.cardExpYear
146	            ? `${String(user.cardExpMonth).padStart(2, "0")}/${user.cardExpYear}` : null,
147	        }] : []),
148	        ...(user.paypalVaultId ? [{
149	          kind: "paypal" as const,
150	          label: "PayPal",
151	          detail: user.paypalPayerEmail ?? "Vaulted account",
152	          expires: null,
153	        }] : []),
154	      ]}
155	      invoices={invoices.map((i) => ({
156	        id: i.id, number: i.number,
157	        cents: i.amountCents + i.taxCents,
158	        refundedCents: i.refundedCents,
159	        status: i.status,
160	        description: i.description ?? "",
161	        at: (i.paidAt ?? i.periodStart)?.toISOString() ?? null,
162	      }))}
163	      cardOnFile={hasChargeableCard(user)}
164	      isImpersonating={isImpersonating}
165	      autoRecharge={{
166	        enabled: user.autoRechargeEnabled,
167	        thresholdCents: user.autoRechargeThresholdCents,
168	        amountCents: user.autoRechargeAmountCents,
169	      }}
170	      bandwidth={bandwidth}
171	      cards={cards}
172	    />
173	  );
174	}
