"use client";

/**
 * "Pay now" popup for an outstanding renewal balance — built exactly like
 * `CardSetupModal.tsx` (the same `CheckoutElementsProvider` + `PaymentElement` +
 * `currentStripeAppearance`/`STRIPE_FONTS`/`useStripeThemeKey` pattern every
 * other Stripe surface on this platform uses), instead of the old
 * `StripeCheckoutModal`'s `<EmbeddedCheckout>` — Stripe's own prebuilt
 * light-themed page, which is exactly why an unstyled Stripe form dropped into
 * a dark app looked wrong on every OTHER payment surface before it was
 * migrated off (see AddFundsPaymentModal.tsx's doc comment). Outstanding-
 * balance settle (`createOutstandingEmbedded`, lib/stripe-cards.ts) was the one
 * Stripe surface left on the old `embedded_page` mode; it now opens the same
 * Custom Checkout session shape as everything else.
 *
 * The caller (`components/nx/BillingView.tsx`) already did the "which server
 * has an outstanding balance" work and calls `settleOutstanding` — this
 * component is presentation + payment-confirmation only, same division as
 * CardSetupModal.
 */

import { useMemo, useState } from "react";
import { createPortal } from "react-dom";
import {
  CheckoutElementsProvider,
  useCheckoutElements,
  PaymentElement,
} from "@stripe/react-stripe-js/checkout";
import { currentStripeAppearance, useStripeThemeKey, STRIPE_FONTS, stripeFor } from "@/components/customer/PaymentStep";

const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

function LockIcon({ className = "h-3.5 w-3.5" }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" className={className}>
      <rect x="5" y="10.5" width="14" height="9" rx="1.7" />
      <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
    </svg>
  );
}

/** Renders inside `<CheckoutElementsProvider>` — the only place `useCheckoutElements()` is valid. */
function SettleBalanceForm({ amountCents, hostname }: { amountCents: number | null; hostname: string }) {
  const checkoutState = useCheckoutElements();
  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function pay() {
    if (!checkoutActions) return;
    setError(null);
    setConfirming(true);
    try {
      const result = await checkoutActions.confirm();
      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another.");
      // On success Stripe navigates the browser to the session's return_url —
      // /api/stripe/confirm, the same fulfilment every other payment on this
      // platform runs through.
    } catch {
      setError("Something went wrong confirming your payment. Please try again.");
    } finally {
      setConfirming(false);
    }
  }

  return (
    <div className="space-y-4">
      <p className="text-[12.5px] leading-[1.5] text-slate-400">
        Settles the outstanding renewal for <span className="font-semibold text-slate-200">{hostname}</span>.
        Applied to your wallet and used to restore the server automatically.
      </p>
      <div>
        <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
          <LockIcon /> Card details
        </label>
        <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
          <PaymentElement
            options={{
              layout: "tabs",
              fields: { billingDetails: { name: "auto" } },
              paymentMethodOrder: ["card"],
            }}
          />
        </div>
      </div>

      {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}

      <button
        type="button"
        onClick={pay}
        disabled={confirming || !checkoutActions?.canConfirm}
        className="btn-deploy w-full py-3 text-sm"
      >
        <LockIcon className="h-4 w-4" />
        {confirming ? "Processing…" : amountCents !== null ? `Pay ${money(amountCents)} now` : "Pay now"}
        {!confirming && <span className="dep-arrow">→</span>}
      </button>
      <p className="text-center text-[11px] text-slate-500">
        Card numbers are entered directly into Stripe&apos;s secure fields — they never touch Nxeon&apos;s servers.
      </p>
    </div>
  );
}

export function SettleBalanceModal({
  clientSecret,
  publishableKey,
  amountCents,
  hostname,
  onClose,
}: {
  clientSecret: string;
  publishableKey: string;
  amountCents: number | null;
  hostname: string;
  onClose: () => void;
}) {
  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);
  const themeKey = useStripeThemeKey();

  // Portaled to document.body for the same reason CardSetupModal/
  // AddFundsPaymentModal are — an ancestor's transform would otherwise become
  // the containing block for this `fixed` dialog and clip most of it off-screen.
  return createPortal(
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label="Pay outstanding balance"
    >
      <div className="relative my-auto w-full max-w-md rounded-2xl border border-white/10 bg-navy-950 p-5 shadow-2xl">
        <div className="flex items-center justify-between pb-4">
          <p className="text-sm font-semibold text-slate-100">Pay outstanding balance</p>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
          >
            ✕
          </button>
        </div>

        <CheckoutElementsProvider
          key={themeKey}
          stripe={stripePromise}
          options={{ clientSecret, elementsOptions: { appearance: currentStripeAppearance(), fonts: STRIPE_FONTS } }}
        >
          <SettleBalanceForm amountCents={amountCents} hostname={hostname} />
        </CheckoutElementsProvider>
      </div>
    </div>,
    document.body,
  );
}

