 * suspended-for-non-payment server from THIS dashboard was a wallet balance
 * (SubscriptionControls' "Pay & restore", on the per-server page only). A
 * customer with no wallet balance but a working card had no path here at all.
 * One row per suspended-unpaid server, because `settleOutstanding` prices and
 * charges exactly one server's renewal at a time. */
function OutstandingBalanceBanner({ servers }: { servers: OutstandingServer[] }) {
  return (
    <div className="flex flex-col gap-2.5 rounded-[12px] border border-amber-500/30 bg-amber-500/[0.07] px-4 py-3">
      {servers.map((s) => (
        <div key={s.serverId} className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex min-w-0 items-center gap-2.5">
            <Icon name="warntriangle" size={16} className="flex-none text-amber" />
            <span className="trunc text-[12.5px] text-white">
              <span className="font-bold">{s.hostname}</span> is suspended — outstanding balance unpaid.
            </span>
          </div>
          <SettleNowTrigger serverId={s.serverId} hostname={s.hostname} />
        </div>
      ))}
    </div>
  );
}

/**
 * Mints a fresh embedded Checkout session on click (see `settleOutstanding`'s
 * doc comment for why it's never reused) and mounts it in `SettleBalanceModal`.
 *
 * `covered: true` is NOT a failure — the wallet already funds the renewal and
 * the sweep applies it automatically — so it gets the same neutral styling the
 * old (unwired) `SettleNowButton` gave it, not the error color.
 */
function SettleNowTrigger({ serverId, hostname }: { serverId: string; hostname: string }) {
  const [pending, start] = useTransition();
  const [message, setMessage] = useState<{ tone: "info" | "error"; text: string } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; amountCents: number | null } | null>(null);

  const pay = () => {
    setMessage(null);
    start(async () => {
      const res = await settleOutstanding(serverId);
      if (res.checkout) {
        setCheckout({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey, amountCents: res.amountCents ?? null });
        return;
      }
      setMessage({
        tone: res.covered ? "info" : "error",
        text: res.error ?? "We couldn't start checkout. Please try again in a moment.",
      });
    });
  };

  return (
    <div className="flex flex-none flex-col items-end gap-1">
      <button type="button" onClick={pay} disabled={pending} className="btn-primary h-[30px] px-3.5 text-[11.5px]">
        {pending ? "Opening checkout…" : "Pay now"}
      </button>
      {message && (
        <p className={"text-[10.5px] " + (message.tone === "info" ? "text-tx-faint" : "text-rose")}>{message.text}</p>
      )}
      {checkout && (
        <SettleBalanceModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          amountCents={checkout.amountCents}
          hostname={hostname}
          onClose={() => setCheckout(null)}
        />
      )}
    </div>
  );
}

